use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use ring::hmac;

const CIRCUIT_BREAKER_THRESHOLD: u32 = 5;
const CIRCUIT_BREAKER_RESET_MS: u64 = 30000;
const SIGNATURE_WINDOW_SECS: u64 = 300;
const NONCE_CACHE_CAPACITY: usize = 10000;

#[derive(Clone, Debug, PartialEq)]
enum CircuitState {
    Closed,
    Open(Instant),
    HalfOpen,
}

struct CircuitBreaker {
    state: CircuitState,
    failure_count: u32,
    success_count: u32,
}

impl CircuitBreaker {
    fn new() -> Self {
        Self { state: CircuitState::Closed, failure_count: 0, success_count: 0 }
    }

    fn record_failure(&mut self) {
        self.failure_count += 1;
        if self.failure_count >= CIRCUIT_BREAKER_THRESHOLD {
            self.state = CircuitState::Open(Instant::now());
        }
    }

    fn record_success(&mut self) {
        match self.state {
            CircuitState::HalfOpen => {
                self.success_count += 1;
                if self.success_count >= 3 {
                    self.state = CircuitState::Closed;
                    self.failure_count = 0;
                    self.success_count = 0;
                }
            }
            _ => { self.failure_count = 0; }
        }
    }

    fn can_proceed(&mut self) -> bool {
        match self.state {
            CircuitState::Closed => true,
            CircuitState::Open(opened_at) => {
                if opened_at.elapsed() > Duration::from_millis(CIRCUIT_BREAKER_RESET_MS) {
                    self.state = CircuitState::HalfOpen;
                    true
                } else {
                    false
                }
            }
            CircuitState::HalfOpen => true,
        }
    }
}

struct NonceCache {
    seen: HashSet<String>,
    timestamps: Vec<(String, u64)>,
}

impl NonceCache {
    fn new() -> Self {
        Self { seen: HashSet::new(), timestamps: Vec::new() }
    }

    fn check_and_insert(&mut self, nonce: &str, msg_timestamp: u64) -> bool {
        self.evict_expired();
        if self.seen.contains(nonce) {
            return false;
        }
        if self.seen.len() >= NONCE_CACHE_CAPACITY {
            self.evict_oldest();
        }
        self.seen.insert(nonce.to_string());
        self.timestamps.push((nonce.to_string(), msg_timestamp));
        true
    }

    fn evict_expired(&mut self) {
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let cutoff = now.saturating_sub(SIGNATURE_WINDOW_SECS);
        self.timestamps.retain(|(n, ts)| {
            if *ts < cutoff {
                self.seen.remove(n);
                false
            } else {
                true
            }
        });
    }

    fn evict_oldest(&mut self) {
        if let Some((n, _)) = self.timestamps.first() {
            self.seen.remove(&n.clone());
            self.timestamps.remove(0);
        }
    }
}

pub struct MessageConsumer {
    signing_key: hmac::Key,
    circuit_breaker: Arc<Mutex<CircuitBreaker>>,
    nonce_cache: Arc<Mutex<NonceCache>>,
    processed: Arc<Mutex<Vec<String>>>,
}

impl MessageConsumer {
    pub fn new(secret: &[u8]) -> Self {
        Self {
            signing_key: hmac::Key::new(hmac::HMAC_SHA256, secret),
            circuit_breaker: Arc::new(Mutex::new(CircuitBreaker::new())),
            nonce_cache: Arc::new(Mutex::new(NonceCache::new())),
            processed: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn consume_message(&self, payload: &str, timestamp: u64, nonce: &str, signature: &[u8]) -> Result<(), String> {
        let mut cb = self.circuit_breaker.lock().unwrap();
        if !cb.can_proceed() {
            return Err("circuit open".to_string());
        }
        drop(cb);

        match self.verify_and_process(payload, timestamp, nonce, signature) {
            Ok(()) => {
                let mut cb = self.circuit_breaker.lock().unwrap();
                cb.record_success();
                Ok(())
            }
            Err(e) => {
                let mut cb = self.circuit_breaker.lock().unwrap();
                cb.record_failure();
                Err(e)
            }
        }
    }

    fn verify_and_process(&self, payload: &str, timestamp: u64, nonce: &str, signature: &[u8]) -> Result<(), String> {
        // Step 1: Verify timestamp freshness
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        if now.saturating_sub(timestamp) > SIGNATURE_WINDOW_SECS {
            return Err("message expired".to_string());
        }
        if timestamp > now + 60 {
            return Err("message from future".to_string());
        }

        // Step 2: Verify HMAC signature
        let signing_content = format!("{}:{}:{}", payload, timestamp, nonce);
        hmac::verify(&self.signing_key, signing_content.as_bytes(), signature)
            .map_err(|_| "invalid signature".to_string())?;

        // Step 3: Check nonce for replay (AFTER signature verification)
        let mut cache = self.nonce_cache.lock().unwrap();
        if !cache.check_and_insert(nonce, timestamp) {
            return Err("duplicate nonce".to_string());
        }
        drop(cache);

        // Step 4: Process the message
        let mut processed = self.processed.lock().unwrap();
        processed.push(payload.to_string());
        Ok(())
    }

    pub fn get_processed(&self) -> Vec<String> {
        self.processed.lock().unwrap().clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_flow() {
        let consumer = MessageConsumer::new(b"secret-key-123");
        let key = hmac::Key::new(hmac::HMAC_SHA256, b"secret-key-123");
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let content = format!("hello:{}:nonce1", now);
        let sig = hmac::sign(&key, content.as_bytes());
        assert!(consumer.consume_message("hello", now, "nonce1", sig.as_ref()).is_ok());
    }
}
